+    recipes: [{
+      key: "trail_bread",
+      outputIdentity: "food_trail_bread",
+      outputName: "Trail Bread",
+      requirements: { flour: 1, wheat: 1, water: 1, firewood: 1 },
+      consumes: { flour: 1, wheat: 1, firewood: 1 },
+      canCraft: false,
+    }],
+  });
