    int: (min) => min,
    choice: (arr) => arr[0],
    float: (min) => min,
  };

  const spawns = populateChunk(chunk, floorPlan, rng);
  const spawners = spawns.filter((s) => s.kind === 'spawner');
  assert(spawners.length > 0, 'expected at least one spawner');
