  for (const request of homeRequests) {
    const { building, role } = request;
    const placed = placeBuilding(
      chunks,
      bounds,
      {
        key: `${building.key}_${role}_home`,
        defKey: "cottage",
        district: building.district,
        coreDx: 4,
        coreDy: 5,
        wants: ["flat"],
