      building.door || townCenter,
      occupied,
      protectedTiles,
      seed ^ hashKey(`${building.key}:${role}:home`),
      townCenter,
    );
    if (!placed) continue;
    homes.set(role, placed);
    buildings.push(placed);
  }
  return homes;
}

function findChestDropTile(chunks, chest) {
  if (!chest) return null;
  for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
