145:export function installInventoryDataProvider({ world, getActiveSpellId, isSimUiBlocked, getMessageLog, tombstoneRepo }) {
1075:  addEventListener('ui:requestQuestReward', (ev) => {
        questId: String(def.id || ''),
        title: String(questDef?.title || def.id || ''),
        status: String(state.status || 'active'),
        node: String(state.node || ''),
        t0: Number(state.t0 || 0),
        summary: String(vars?.data?.objective || ''),
        flavorText: questJournalFlavorText(questDef, vars?.data, def.id),
        rewardText,
        rewardItems: listQuestRewardItems(questDef, vars?.data).map((item) => ({
          itemId: item.itemId,
          name: item.name,
          description: item.description,
          count: item.count,
          tooltip: item.tooltip,
          choiceId: item.choiceId,
          choiceLabel: item.choiceLabel,
        })),
        rewardGold: Math.max(0, Number(vars?.data?.rewardGold || questDef?.journal?.rewardGold || 0) | 0),
        completionText,
        progress: Math.max(0, Number(vars?.data?.progress || 0) | 0),
        target: Math.max(0, Number(vars?.data?.target || 0) | 0),
        checklist: Array.isArray(vars?.data?.checklist)
          ? vars.data.checklist.map((entry) => ({
            text: String(entry?.text || ''),
            done: !!entry?.done,
          }))
          : [],
      };
      const prev = questMap.get(rec.questId);
      if (!prev || rec.t0 >= prev.t0) questMap.set(rec.questId, rec);
    }
    const quests = Array.from(questMap.values()).sort((a, b) => a.t0 - b.t0 || a.title.localeCompare(b.title));
    _uiEventTarget.dispatchEvent(new CustomEvent('ui:questJournalData', { detail: { quests } }));
  });

  addEventListener('ui:requestQuestReward', (ev) => {
    const questId = String(ev?.detail?.questId || '').trim();
    const rewardId = String(ev?.detail?.rewardId || '').trim();
    const playerId = Number(playerEntity(world)?.id || 0) | 0;
    if (!questId || !rewardId || !(playerId > 0)) return;
    world.emit('quest:reward_selected', { questId, playerId, rewardId });
    const rewardStillPending = Array.from(world.query(QuestDefRef, QuestState, QuestBindings))
      .some(([, def, state, bindings]) => String(def?.id || '') === questId
        && Number(bindings?.player || 0) === playerId
        && String(state?.node || '') === 'reward'
        && String(state?.status || '') === 'active');
    if (rewardStillPending) {
      _uiEventTarget.dispatchEvent(new CustomEvent('ui:questRewardError', {
        detail: { questId, message: 'Make room in your inventory before claiming this reward.' },
      }));
    } else {
      _uiEventTarget.dispatchEvent(new CustomEvent('ui:questRewardCompleted', {
        detail: { questId, rewardId },
      }));
    }
    _uiEventTarget.dispatchEvent(new CustomEvent('ui:requestQuestJournalData'));
  });

  world.on('quest:advanced', (payload) => {
    if (/choose (?:your|one|the town) reward/i.test(String(payload?.objective || ''))) {
      queueMicrotask(() => _uiEventTarget.dispatchEvent(new CustomEvent('ui:openQuestReward', {
        detail: { questId: String(payload?.questId || '') },
      })));
    }
  });

  return { buildGroundPickupDetailAt };
}
